mapper.select:
SELECT user_birth, user_gender, a.user_id, a.login_time as userLastloginTime, a.user_mobile, b.user_reg_time, user_truename FROM ${database.prefix.userms}hou_user_live_statistics a LEFT JOIN ${database.prefix.userms}hou_user_info_detail b ON a.user_id = b.user_id WHERE 1=1
and login_time >= #{param.startTime}
and login_time <= #{param.finishTime}
and plat_form = #{param.platForm}
order by a.login_time desc

SELECT a.plat_form, count( * ) sum FROM ( SELECT count( * ) sum, plat_form FROM ${database.prefix.userms}hou_user_live_statistics where 1=1
and login_time >= #{param.startTime}
and login_time <= #{param.finishTime}
GROUP BY user_id) a GROUP BY a.plat_form
